{
 "genere": "prevedi",
 "titolo": "Previsioni: Vettori e rotazioni in 3D",
 "consegna": "Leggi ogni pezzo di codice e scrivi cosa restituisce, senza eseguirlo. Poi confronta con la risposta vera.",
 "modalita": "previsioni",
 "previsioni": [
  {
   "codice": "extends RefCounted


func run():
	var rad: float = deg_to_rad(90.0)
	return is_equal_approx(rad, PI / 2.0)
",
   "domanda": "Che valore booleano restituisce `run()`?",
   "spiegazione": "`deg_to_rad(90.0)` converte 90 gradi in radianti, che equivalgono esattamente a `PI / 2`. Il confronto con `is_equal_approx` restituisce `true`."
  },
  {
   "codice": "extends RefCounted


func run():
	var forward: Vector3 = Vector3.FORWARD
	var backward: Vector3 = -forward
	return backward.z
",
   "domanda": "Quanto vale `backward.z` alla fine?",
   "spiegazione": "In Godot 3D, `Vector3.FORWARD` punta verso `(0, 0, -1)`. Negando il vettore con il segno meno, la coordinata `z` cambia segno e diventa `1.0`, corrispondente alla direzione indietro."
  },
  {
   "codice": "extends Node3D


func run():
	rotate_y(deg_to_rad(90.0))
	return int(round(rad_to_deg(rotation.y)))
",
   "domanda": "Quanto vale la rotazione y in gradi alla fine?",
   "spiegazione": "`rotate_y()` ruota il nodo attorno all'asse Y della quantità passata in radianti. Applicando 90 gradi convertiti, la proprietà `rotation.y` memorizza quel valore; riconvertendolo in gradi otteniamo 90."
  },
  {
   "codice": "extends RefCounted


func run():
	var current: float = 0.0
	var target: float = 1.0
	var max_delta: float = 0.5
	return rotate_toward(current, target, max_delta)
",
   "domanda": "Quanto vale il risultato di `rotate_toward`?",
   "spiegazione": "`rotate_toward` sposta l'angolo corrente verso quello bersaglio senza superarlo, rispettando il limite massimo (`max_delta`). Partendo da 0.0 e potendo avanzare di 0.5, il valore finale è esattamente 0.5."
  },
  {
   "codice": "extends RefCounted


func run():
	var target_pos := Vector3(0, 0, -5)
	var current_pos := Vector3(0, 0, 0)
	var dir := target_pos - current_pos
	return dir.z
",
   "domanda": "Quanto vale `dir.z` alla fine?",
   "spiegazione": "La direzione da un punto all'altro si calcola sottraendo la posizione di partenza (`current_pos`) da quella di arrivo (`target_pos`). Di conseguenza, `(-5) - 0` dà `-5.0`."
  }
 ]
